{"function": "Counting paper", "situation": "At an office, asking a colleague how many sheets of paper they need.", "cue": "Ask your colleague how many sheets of paper they need.", "text": "คุณต้องการกระดาษกี่ใบครับ", "english": "How many sheets of paper do you need?", "speaker": "male"},
{"function": "Pointing out one item", "situation": "Looking at two similar items, asking which one is yours.", "cue": "Ask your friend if that flat object is yours.", "text": "ใบนั้นของคุณใช่ไหมครับ", "english": "Is that one yours?", "speaker": "male"},
{"function": "Describing quantity", "situation": "At a restaurant, discussing how many plates of food to order.", "cue": "Ask your friend how many plates of food we should order.", "text": "เราสั่งอาหารกี่ใบดีครับ", "english": "How many plates of food should we order?", "speaker": "male"},
{"function": "Identifying item", "situation": "You have received a document and want to confirm it's the correct one.", "cue": "Ask if this is the correct document.", "text": "ใบนี้ใช่ไหมคะ", "english": "Is this the one?", "speaker": "female"},
{"function": "Counting items", "situation": "Asking a shopkeeper how many items were purchased.", "cue": "Ask the shopkeeper how many items were bought.", "text": "ซื้อของไปกี่ใบครับ", "english": "How many items were bought?", "speaker": "male"},
{"function": "Asking for a specific item", "situation": "At a shop, asking for a specific type of document.", "cue": "Ask if they have that type of document.", "text": "มีใบนั้นไหมครับ", "english": "Do you have that kind?", "speaker": "male"}
]}

